<?php require __DIR__.'/config/bootstrap.php'; $slug=$_GET['slug']??''; if(!$slug){$title='Categories';require __DIR__.'/includes/header.php';$cs=db()->query("SELECT * FROM categories WHERE status=1 ORDER BY name")->fetchAll();echo '<h1>Categories</h1><div class="grid">';foreach($cs as $c)echo '<div class="card"><div class="pad"><h2><a href="category.php?slug='.e($c['slug']).'">'.e($c['name']).'</a></h2><p>'.e($c['description']).'</p></div></div>';echo '</div>';require __DIR__.'/includes/footer.php';exit;} $st=db()->prepare("SELECT * FROM categories WHERE slug=? AND status=1");$st->execute([$slug]);$cat=$st->fetch();if(!$cat){http_response_code(404);exit('404');}$title=$cat['name'].' · '.setting('site_name','PlayGramBlog');require __DIR__.'/includes/header.php';$st=db()->prepare("SELECT p.*,u.name author FROM posts p LEFT JOIN users u ON u.id=p.author_id WHERE p.category_id=? AND p.status='published' AND p.published_at<=NOW() ORDER BY p.published_at DESC");$st->execute([$cat['id']]);?><h1><?=e($cat['name'])?></h1><p><?=e($cat['description'])?></p><div class="grid"><?php foreach($st as $p): ?><article class="card"><div class="pad"><h2><a href="post.php?slug=<?=e($p['slug'])?>"><?=e($p['title'])?></a></h2><p><?=e(excerpt($p['content']))?></p></div></article><?php endforeach;?></div><?php require __DIR__.'/includes/footer.php';?>